import{_ as t,c as i,o as a,ao as o}from"./chunks/framework.DAsozCiY.js";const p=JSON.parse('{"title":"Pogget Inspiration Hub Service Agreement","description":"","frontmatter":{"next":false},"headers":[],"relativePath":"en/agreement/pogget-vui-service.md","filePath":"en/agreement/pogget-vui-service.md"}'),n={name:"en/agreement/pogget-vui-service.md"};function r(s,e,l,c,h,d){return a(),i("div",null,e[0]||(e[0]=[o('<h1 id="pogget-inspiration-hub-service-agreement" tabindex="-1">Pogget Inspiration Hub Service Agreement <a class="header-anchor" href="#pogget-inspiration-hub-service-agreement" aria-label="Permalink to &quot;Pogget Inspiration Hub Service Agreement&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Version</p><p>Initial Release Date: November 9, 2025</p><p>Last Updated Date: November 9, 2025</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Vilinko Studio is registered in Chinese Mainland, which means that when handling service requests from outside Chinese Mainland, we will comply with the relevant laws of the People&#39;s Republic of China. Your personal data will be processed in accordance with the applicable laws and regulations of the People&#39;s Republic of China.</p></div><p>In case of any conflict, the <a href="/agreement/pogget-vui-service.html"><strong>Simplified Chinese version</strong></a> shall prevail.</p><h2 id="_1-general-provisions" tabindex="-1">1. General Provisions <a class="header-anchor" href="#_1-general-provisions" aria-label="Permalink to &quot;1. General Provisions&quot;">​</a></h2><h3 id="_1-1-contracting-parties-and-scope" tabindex="-1">1.1 Contracting Parties and Scope <a class="header-anchor" href="#_1-1-contracting-parties-and-scope" aria-label="Permalink to &quot;1.1 Contracting Parties and Scope&quot;">​</a></h3><p>This Pogget Inspiration Hub Service Agreement (hereinafter referred to as &quot;this Agreement&quot;) is jointly concluded between Vilinko Studio (hereinafter referred to as &quot;the Company&quot; or &quot;the Platform Operator&quot;) and the user (hereinafter referred to as &quot;User&quot; or &quot;You&quot;) who utilizes the Pogget Inspiration Hub service. This Agreement is intended to regulate the respective rights, obligations, and responsibilities of the User during their use of the service.</p><h3 id="_1-2-agreement-effect-and-modifications" tabindex="-1">1.2 Agreement Effect and Modifications <a class="header-anchor" href="#_1-2-agreement-effect-and-modifications" aria-label="Permalink to &quot;1.2 Agreement Effect and Modifications&quot;">​</a></h3><ol><li>This Agreement includes the main body of the agreement and all various rules, announcements, notices, etc., already published or potentially published by the Platform in the future. All rules are integral parts of this Agreement and possess the same legal effect as the main body of this Agreement.</li><li>The Company reserves the right to modify the terms of this Agreement when necessary. The modified agreement will be displayed prominently on the Platform. Upon the expiry of seven days from the date of display, it shall be deemed that the User has been notified. If the User does not agree with the relevant modifications, they shall immediately cease using the service; continued use of the service shall be deemed as acceptance of the modified agreement.</li><li>These terms are supplementary to the &quot;Vilinko Studio Software Service Agreement&quot; , and have the same legal effect as the above agreements. If there is any inconsistency between these terms and other agreements, these terms shall prevail.</li></ol><h2 id="_2-definitions-and-interpretation" tabindex="-1">2. Definitions and Interpretation <a class="header-anchor" href="#_2-definitions-and-interpretation" aria-label="Permalink to &quot;2. Definitions and Interpretation&quot;">​</a></h2><h3 id="_2-1-definition-of-terms" tabindex="-1">2.1 Definition of Terms <a class="header-anchor" href="#_2-1-definition-of-terms" aria-label="Permalink to &quot;2.1 Definition of Terms&quot;">​</a></h3><ol><li><strong>&quot;Pogget Inspiration Hub&quot;</strong>: Refers to the digital content sharing platform built into the Pogget computer execution program, providing users with comprehensive online services including uploading, displaying, disseminating, and downloading custom components.</li><li><strong>&quot;Custom Component&quot;</strong>: Refers to a digital work developed by the user through technical specifications recognized by the Platform, capable of realizing specific functions within the Pogget program runtime environment, including but not limited to functional modules, interface themes, special effects materials, etc.</li><li><strong>&quot;Feishu Document System&quot;</strong>: Refers to the user information collection and processing platform adopted by the Company, used for the standardized collection, desensitization processing, and categorized storage of user-submitted content.</li><li><strong>&quot;User Identity Identifier&quot;</strong>: Refers to a digitally encrypted and obfuscated identity recognition code automatically embedded by the Platform&#39;s technical system after a component passes review, used for component traceability and copyright protection.</li></ol><h2 id="_3-service-content-and-specifications" tabindex="-1">3. Service Content and Specifications <a class="header-anchor" href="#_3-service-content-and-specifications" aria-label="Permalink to &quot;3. Service Content and Specifications&quot;">​</a></h2><h3 id="_3-1-description-of-service-scope" tabindex="-1">3.1 Description of Service Scope <a class="header-anchor" href="#_3-1-description-of-service-scope" aria-label="Permalink to &quot;3.1 Description of Service Scope&quot;">​</a></h3><p>Pogget Inspiration Hub provides users with the following professional technical services:</p><ol><li><strong>Component Collection Service</strong>: Receives user-submitted custom components according to the <u>technical specifications formulated by the Platform</u>.</li><li><strong>Content Review Service</strong>: Conducts <u>content compliance review</u> and <u>technical security detection</u> on user-submitted components.</li><li><strong>Component Distribution Service</strong>: Provides platform display and network distribution services for <u>components that have passed review</u>.</li><li><strong>Technical Support Service</strong>: Provides <u>technical guidance</u> and <u>operational maintenance support</u> for component developers.</li></ol><h3 id="_3-2-service-standards-and-warranty" tabindex="-1">3.2 Service Standards and Warranty <a class="header-anchor" href="#_3-2-service-standards-and-warranty" aria-label="Permalink to &quot;3.2 Service Standards and Warranty&quot;">​</a></h3><ol><li>The Company will take reasonable technical measures in accordance with industry standards to ensure the stable operation of the service.</li><li>The User understands and agrees that the Company shall not bear any responsibility for temporary service interruptions caused by factors such as system maintenance, upgrades, or force majeure.</li></ol><h2 id="_4-user-rights-and-obligations" tabindex="-1">4. User Rights and Obligations <a class="header-anchor" href="#_4-user-rights-and-obligations" aria-label="Permalink to &quot;4. User Rights and Obligations&quot;">​</a></h2><h3 id="_4-1-basic-user-rights" tabindex="-1">4.1 Basic User Rights <a class="header-anchor" href="#_4-1-basic-user-rights" aria-label="Permalink to &quot;4.1 Basic User Rights&quot;">​</a></h3><p>Subject to strict compliance with this Agreement, the User enjoys the following basic rights:</p><ol><li><strong>Component Upload Right</strong>: The right to submit custom components that meet the requirements in accordance with the Platform&#39;s technical specifications.</li><li><strong>Component Use Right</strong>: A non-exclusive right to download and use components that have been listed on the Platform.</li><li><strong>Content Management Right</strong>: The right to perform management operations such as updating or delisting components uploaded by oneself.</li><li><strong>Violation Reporting Right</strong>: The right to report违规 content within the Platform through real-name or anonymous reporting.</li></ol><h3 id="_4-2-user-obligations-and-responsibilities" tabindex="-1">4.2 User Obligations and Responsibilities <a class="header-anchor" href="#_4-2-user-obligations-and-responsibilities" aria-label="Permalink to &quot;4.2 User Obligations and Responsibilities&quot;">​</a></h3><p>The User undertakes to strictly comply with the following obligations:</p><ol><li>Ensure that all submitted information is true, accurate, complete, and complies with legal and regulatory requirements.</li><li>Ensure that uploaded components do not infringe upon any legitimate rights and interests of any third party.</li><li>Timely maintain and update the content of components uploaded by oneself.</li><li>Cooperate with the Platform in necessary identity verification and content review.</li></ol><h2 id="_5-platform-rights-and-responsibilities" tabindex="-1">5. Platform Rights and Responsibilities <a class="header-anchor" href="#_5-platform-rights-and-responsibilities" aria-label="Permalink to &quot;5. Platform Rights and Responsibilities&quot;">​</a></h2><h3 id="_5-1-platform-management-authority" tabindex="-1">5.1 Platform Management Authority <a class="header-anchor" href="#_5-1-platform-management-authority" aria-label="Permalink to &quot;5.1 Platform Management Authority&quot;">​</a></h3><p>To ensure the healthy development of the platform ecosystem, the Company reserves the following management authorities:</p><ol><li><strong>Content Review Right</strong>: To conduct substantive review of <u>all components submitted by users</u>, ensuring compliance with the Platform&#39;s technical specifications and legal and regulatory requirements.</li><li><strong>Content Disposition Right</strong>: To take measures such as <u>deletion, modification, delisting</u> against components that <u>violate regulations</u>, maintaining platform order and user rights.</li><li><strong>Account Management Right</strong>: To take actions such as <u>warning, function restriction, account suspension</u> against <u>violating users</u>, protecting user privacy and platform security.</li><li><strong>Service Management Right</strong>: To adjust service content or suspend service operations through <u>announcement methods</u>, ensuring user satisfaction and platform operational efficiency.</li></ol><h3 id="_5-2-limitation-of-platform-liability" tabindex="-1">5.2 Limitation of Platform Liability <a class="header-anchor" href="#_5-2-limitation-of-platform-liability" aria-label="Permalink to &quot;5.2 Limitation of Platform Liability&quot;">​</a></h3><ol><li><strong>The Company makes no express or implied warranties regarding the legality or accuracy of user-generated content.</strong></li><li>The Company <u>shall not bear legal liability</u> for any direct or indirect losses caused by <u>user actions</u>.</li><li>The Company <u>does not guarantee</u> that the service&#39;s <u>continuity, timeliness, or security will remain unaffected</u>.</li></ol><h2 id="_6-intellectual-property-protection" tabindex="-1">6. Intellectual Property Protection <a class="header-anchor" href="#_6-intellectual-property-protection" aria-label="Permalink to &quot;6. Intellectual Property Protection&quot;">​</a></h2><h3 id="_6-1-ownership-of-rights" tabindex="-1">6.1 Ownership of Rights <a class="header-anchor" href="#_6-1-ownership-of-rights" aria-label="Permalink to &quot;6.1 Ownership of Rights&quot;">​</a></h3><ol><li>The Platform Operator independently owns the intellectual property rights related to this service, including but not limited to <u>trademark rights, patent rights, copyrights</u>.</li><li>The User retains the <u>original</u> intellectual property rights to the components they upload.</li></ol><h3 id="_6-2-license-grant" tabindex="-1">6.2 License Grant <a class="header-anchor" href="#_6-2-license-grant" aria-label="Permalink to &quot;6.2 License Grant&quot;">​</a></h3><p><u>Uploading a component by the User shall be deemed as granting the Company a worldwide, royalty-free, irrevocable, non-exclusive license to use, reproduce, modify, and disseminate the component content for the purpose of providing the service.</u></p><h3 id="_6-3-identifier-technical-measures" tabindex="-1">6.3 Identifier Technical Measures <a class="header-anchor" href="#_6-3-identifier-technical-measures" aria-label="Permalink to &quot;6.3 Identifier Technical Measures&quot;">​</a></h3><p>To protect intellectual property, the Company will implement the following technical measures after a component passes review:</p><ol><li>Embed an encrypted user identity recognition code.</li><li>Add digital signature information for component verification.</li><li>Employ anti-tampering technologies to protect component integrity. The User acknowledges and agrees to the implementation of the aforementioned technical measures.</li></ol><h2 id="_7-privacy-and-data-protection" tabindex="-1">7. Privacy and Data Protection <a class="header-anchor" href="#_7-privacy-and-data-protection" aria-label="Permalink to &quot;7. Privacy and Data Protection&quot;">​</a></h2><h3 id="_7-1-information-collection-scope" tabindex="-1">7.1 Information Collection Scope <a class="header-anchor" href="#_7-1-information-collection-scope" aria-label="Permalink to &quot;7.1 Information Collection Scope&quot;">​</a></h3><p>The Company collects the following information through the Feishu Document System:</p><ol><li><u>WeChat, QQ, and email information</u> filled in by the User during their first component upload.</li><li>File data of VUI components uploaded by the User.</li><li>User browser information, IP address, etc., that may be automatically collected when filling out Feishu forms.</li></ol><h3 id="_7-2-information-usage-standards" tabindex="-1">7.2 Information Usage Standards <a class="header-anchor" href="#_7-2-information-usage-standards" aria-label="Permalink to &quot;7.2 Information Usage Standards&quot;">​</a></h3><ol><li>Strictly adhere to the principles of &quot;Legality, Justification, Necessity&quot; when using user information.</li><li>Perform <u>desensitization processing and encrypted storage</u> on <u>user personal information</u>.</li><li>Establish a strict data access permission management system.</li><li>Conduct regular information security risk assessments and audits.</li><li>For more detailed privacy policy, please refer to the &quot;Vilinko Studio Privacy Policy&quot;.</li></ol><h2 id="_8-disclaimer" tabindex="-1">8. Disclaimer <a class="header-anchor" href="#_8-disclaimer" aria-label="Permalink to &quot;8. Disclaimer&quot;">​</a></h2><h3 id="_8-1-exemption-circumstances" tabindex="-1">8.1 Exemption Circumstances <a class="header-anchor" href="#_8-1-exemption-circumstances" aria-label="Permalink to &quot;8.1 Exemption Circumstances&quot;">​</a></h3><p>The Company shall not be liable under the following circumstances:</p><ol><li>Service interruption or data loss caused by <u>force majeure</u>.</li><li>Losses or damages caused by <u>improper user operation</u>.</li><li>Disputes or losses arising from <u>actions of third parties</u>.</li><li>Consequences resulting from the User&#39;s violation of this Agreement.</li></ol><h2 id="_9-supplementary-provisions" tabindex="-1">9. Supplementary Provisions <a class="header-anchor" href="#_9-supplementary-provisions" aria-label="Permalink to &quot;9. Supplementary Provisions&quot;">​</a></h2><h3 id="_9-1-dispute-resolution" tabindex="-1">9.1 Dispute Resolution** <a class="header-anchor" href="#_9-1-dispute-resolution" aria-label="Permalink to &quot;9.1 Dispute Resolution**&quot;">​</a></h3><p>Any dispute arising from this Agreement shall be resolved through friendly negotiation between the parties. If negotiation fails, either party has the right to file a lawsuit with the competent people&#39;s court in the location of the Company.</p><h3 id="_9-2-service-of-notices" tabindex="-1">9.2 Service of Notices <a class="header-anchor" href="#_9-2-service-of-notices" aria-label="Permalink to &quot;9.2 Service of Notices&quot;">​</a></h3><p>The Company will send legal documents to the User through the following methods:</p><ol><li>Platform announcements.</li><li>User&#39;s registered email address.</li><li>Station message system. Legal documents sent via the aforementioned methods shall be deemed served from the date of dispatch.</li></ol><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><ol><li>If you have questions about this agreement, please email us at <a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a>. We will respond within 7 business days.</li><li>Feishu User Agreement: <a href="https://www.feishu.cn/terms" target="_blank" rel="noreferrer">https://www.feishu.cn/terms</a></li><li>Feishu Privacy Policy: <a href="https://www.feishu.cn/privacy" target="_blank" rel="noreferrer">https://www.feishu.cn/privacy</a></li><li>Feishu Security and Compliance: <a href="https://www.feishu.cn/security" target="_blank" rel="noreferrer">https://www.feishu.cn/security</a></li></ol>',57)]))}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
